WITH enriched AS (SELECT *, LAG(duration_sec, 2) OVER (PARTITION BY page ORDER BY duration_sec, id) AS prev_duration_sec, LEAD(duration_sec, 1) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id) AS next_duration_sec FROM web_events), with_windows AS (SELECT *, SUM(next_duration_sec) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_next_duration_sec, LEAD(duration_sec, 1) OVER w_part AS next_duration_sec_2 FROM enriched WINDOW w_part AS (PARTITION BY session_id ORDER BY event_time, id)), gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM with_windows), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM gaps), filtered AS (SELECT *, DATE_FORMAT(event_time, 'MMM yyyy') AS event_time_label, CEIL(running_next_duration_sec) AS running_next_duration_sec_whole FROM sessionized WHERE event_time > TIMESTAMP '2024-02-21 06:00:00'), flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM filtered), sessions_web_events AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_3 FROM flagged), deduped AS (SELECT * FROM sessions_web_events QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id, page ORDER BY session_start_flag DESC NULLS FIRST, id) = 1) SELECT id, session_id, event_type, page, event_time, prev_duration_sec, next_duration_sec, running_next_duration_sec, next_duration_sec_2 FROM deduped ORDER BY prev_duration_sec DESC NULLS FIRST
